    "summary": "最近在微信、X 和群里面，有一些老板会问我一些 AI 问题，简单的可以几句话就回复掉，但稍微复杂一点的，我还得去看一下他们公司的具体信息和背景，才能给出有价值的回复，可能还有些地方，得稍微动手帮忙搞一搞。 这样吧，我开一个面向老板的企业 AI 落地的顾问尝试，每个月 3 万块钱，3 个月，限 10 家企业，这个价格存对我来说纯粹是交朋友了，也是为了了解下 FDE 这个事情怎么做，给圈友打样下。 我会了解具体公司的一些情况，以及每个公司我会安排一个同事来线上跟进，帮助回答一些具体的问题。 当然，这个价格无法驻场做落地的，核心是线上咨询、方案判断以及简单的落地辅助。 有需求的请联系我或者鱼丸，最好是教育培训、知识付费相关行业的，这样比较接近，但其他领域我应该了解起来也比较容易。",
