    "summary": "刚又被一个海外产品自动扣掉 120 刀，从没用过。 想去看看哪些还在续订，国内信用卡不地道，没批量查询方式，摸索了个办法又扫出一些待扣费的雷。 如果你也是招行信用卡： 1. 打开掌上生活，进入「信用卡」页面 2. 选择信用卡，点击「查账」 3. 更多服务里选择「账单补寄」 4. 选择账单，「近一年全选」+ 前面的第 13 个月补寄账单 5. 收到账单后，导给 AI，让 AI 排查可能仍在付费订阅的产品，及时取消不需要的 其他信用卡应该类似。",
